def compute(vars):
    activity_million = vars["v1"]
    receivables_million = vars["v2"] / 1000
    if receivables_million == 0:
        return None
    percentage = activity_million / receivables_million * 100
    return {
        "value": percentage,
        "trace": {
            "activity_million": activity_million,
            "receivables_million": receivables_million,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
